const VIEWPORTS = [
  { largura: 360, altura: 740, rotulo: '360 px (celular)' },
  { largura: 640, altura: 360, rotulo: '640×360 (≈ zoom de 200% em 1280)' },
  { largura: 768, altura: 1024, rotulo: '768 px (tablet)' },
  { largura: 1366, altura: 768, rotulo: '1366 px (desktop)' },
]

/** Nada vaza para fora da largura da janela: o documento não ganha rolagem horizontal. */
function semRolagemHorizontal() {
  cy.document().then((documento) => {
    const { scrollWidth, clientWidth } = documento.documentElement
    expect(scrollWidth, 'scrollWidth do documento').to.be.at.most(clientWidth)
  })
}

/** O elemento está inteiro dentro da janela, na horizontal. Use com `.should` para repetir até a animação de entrada terminar. */
function dentroDaJanela($elemento: JQuery<HTMLElement>) {
  const { left, right } = $elemento[0].getBoundingClientRect()
  expect(left, 'borda esquerda').to.be.at.least(0)
  expect(right, 'borda direita').to.be.at.most(
    $elemento[0].ownerDocument.defaultView?.innerWidth ?? 0,
  )
}

describe('Plano QA · Responsividade (QUA 03)', () => {
  beforeEach(() => {
    cy.bloquearApi()
    cy.stubApi('GET', '/carteiras*', LISTA, 'listar')
    cy.stubApi('GET', `/carteiras/${CARTEIRA_ID}`, CARTEIRA, 'detalhe')
    cy.stubApi(
      'GET',
      `/carteiras/${CARTEIRA_ID}/versoes*`,
      { items: [], total: 0, page: 1, pageSize: 100 },
      'versoes',
    )
  })

  for (const { largura, altura, rotulo } of VIEWPORTS) {
    it(`QUA 03 · ${rotulo} → admin sem rolagem horizontal, ações alcançáveis e formulário inteiro na tela`, () => {
      cy.viewport(largura, altura)
      cy.stubSessao('admin')

      // Lista de carteiras: tabela no desktop, lista empilhada no celular.
      cy.visit('/admin/carteiras')
      cy.wait('@detalhe')
      // A tabela some no celular (`max-sm:hidden`): procura a carteira no contêiner visível.
      cy.contains(largura < 640 ? 'li' : 'tr', 'Moderada Base').should('be.visible')
      semRolagemHorizontal()
      cy.get('[data-cy="carteira-nova"]').should('be.visible').should(dentroDaJanela)
      if (largura < 640) {
        cy.get('tbody tr').should('not.be.visible')
      } else {
        cy.get('tbody tr').should('be.visible')
      }

      // Formulário de cadastro: todos os campos e o Salvar alcançáveis.
      cy.get('[data-cy="carteira-nova"]').click()
      cy.get('[role="dialog"]').should('be.visible').should(dentroDaJanela)
      for (const campo of ['carteira-nome', 'carteira-perfil', 'carteira-descricao']) {
        cy.get(`[data-cy="${campo}"]`).scrollIntoView().should('be.visible').should(dentroDaJanela)
      }
      cy.get('[data-cy="carteira-salvar"]')
        .scrollIntoView()
        .should('be.visible')
        .should(dentroDaJanela)
      cy.contains('[role="dialog"] button', 'Cancelar').should('be.visible').click()

      // Detalhe: cabeçalho e as quatro abas existem; a faixa de abas rola por dentro, não a página.
      cy.visit(`/admin/carteiras/${CARTEIRA_ID}`)
      cy.contains('h1', 'Moderada Base').should('be.visible')
      cy.get('[role="tab"]').should('have.length', 4)
      semRolagemHorizontal()
      cy.contains('[role="tab"]', 'Relatórios').scrollIntoView().should('be.visible').click()
      cy.get('[data-cy="relatorio-gerar"]')
        .scrollIntoView()
        .should('be.visible')
        .should(dentroDaJanela)
      semRolagemHorizontal()
    })

    it(`QUA 03 · ${rotulo} → catálogo e conta do cliente sem rolagem horizontal e com ações visíveis`, () => {
      cy.viewport(largura, altura)
      cy.stubSessao('cliente')

      cy.visit('/carteiras')
      cy.wait('@detalhe')
      cy.contains('[data-slot="wallet-card"]', 'Moderada Base').should('be.visible')
      semRolagemHorizontal()
      cy.contains('[data-slot="wallet-card"]', 'Moderada Base')
        .find('button')
        .last()
        .should('be.visible')
        .should(dentroDaJanela)

      cy.visit('/conta')
      cy.get('[aria-label="Editar dados da conta"]').should('be.visible').should(dentroDaJanela)
      semRolagemHorizontal()
      cy.get('[aria-label="Editar dados da conta"]').click()
      cy.get('[role="dialog"]').should('be.visible').should(dentroDaJanela)
      cy.contains('[role="dialog"] button', 'Salvar alterações')
        .scrollIntoView()
        .should('be.visible')
        .should(dentroDaJanela)
    })
  }
})

describe('Plano QA · Acessibilidade por teclado (QUA 04)', () => {
  beforeEach(() => {
    cy.bloquearApi()
    cy.stubApi('GET', '/carteiras*', LISTA, 'listar')
    stubLeituraDaCarteira()
  })

  it('QUA 04 · modal de edição da conta aberto e fechado pelo teclado → foco entra no modal e volta ao gatilho ao fechar', () => {
    cy.stubSessao('cliente')
    cy.visit('/conta')

    cy.get('[aria-label="Editar dados da conta"]').focus().type('{enter}')
    cy.get('[role="dialog"]').should('be.visible')
    cy.focused().closest('[role="dialog"]').should('exist')
    cy.get('[role="dialog"]').should('have.attr', 'aria-labelledby').and('not.be.empty')

    // O campo inicial recebe foco dentro do modal (a ordem Tab em si exige teste manual).
    cy.get('body').type('{esc}')
    cy.get('[role="dialog"]').should('not.exist')
    cy.get('[aria-label="Editar dados da conta"]').should('have.focus')
  })

  it('QUA 04 · formulário de carteira com erro → rótulos ligados aos campos e mensagens associadas via aria', () => {
    cy.stubSessao('admin')
    cy.visit('/admin/carteiras')
    cy.wait('@listar')
    cy.get('[data-cy="carteira-nova"]').click()

    // Cada campo tem rótulo clicável (label[for] = id do controle).
    cy.get('[data-cy="carteira-nome"]')
      .invoke('attr', 'id')
      .then((id) => {
        cy.get(`label[for="${id}"]`).should('contain.text', 'Nome da carteira')
      })

    cy.get('[data-cy="carteira-salvar"]').click()
    cy.get('[data-cy="carteira-nome"]')
      .should('have.attr', 'aria-invalid', 'true')
      .invoke('attr', 'aria-describedby')
      .then((descritores) => {
        const ids = String(descritores).split(' ')
        const mensagem = ids.map((id) => `#${CSS.escape(id)}`).join(', ')
        cy.get(mensagem).should('contain.text', 'Informe o nome da carteira')
      })
  })

  it('QUA 04 · abas da carteira → papéis tablist/tab, uma aba selecionada e troca pelo teclado', () => {
    cy.stubSessao('admin')
    cy.visit(`/admin/carteiras/${CARTEIRA_ID}`)

    cy.get('[role="tablist"]').should('have.length', 1)
    cy.get('[role="tab"]').should('have.length', 4)
    cy.get('[role="tab"][aria-selected="true"]')
      .should('have.length', 1)
      .and('contain.text', 'Composição')
    cy.get('[role="tabpanel"][data-state="active"]').should('have.length', 1)

    // Seta para a direita move foco e seleção para a aba seguinte.
    cy.contains('[role="tab"]', 'Composição').focus().type('{rightarrow}')
    cy.contains('[role="tab"]', 'Versões')
      .should('have.attr', 'aria-selected', 'true')
      .and('have.focus')
    cy.get('[role="tab"][aria-selected="true"]').should('have.length', 1)
  })
})

